css:
/* Truck Country brand layer — the few places the design system cannot reach
   from site/tokens.json alone, because blocks.css hard-codes the value. */

/* The shell's side padding comes from the design system, not from --space-4,
   which blocks.css hard-codes for a section's own container. */
.bz-section > .bz-container{padding-inline:var(--container-pad)}
@media (max-width:1100px){.bz-section > .bz-container{padding-inline:var(--container-pad-tablet)}}
@media (max-width:640px){.bz-section > .bz-container{padding-inline:var(--container-pad-mobile)}}

/* Headings are Oswald 700, tight, and uppercase. blocks.css sets 800. */
.bz-block h1,.bz-block h2{font-weight:700}
.bz-block h1{line-height:.98;letter-spacing:-.01em}
.bz-block h2{line-height:1.1;letter-spacing:-.01em}
.bz-block h3{font-weight:600}

/* Buttons: square, Oswald, uppercase, white on red. */
.bz-btn{font-weight:600;font-size:14px;line-height:normal;letter-spacing:.05em;text-transform:uppercase;padding:16px 32px;border-radius:0}
.bz-btn--primary,.bz-btn--primary:hover{color:#fff}
.bz-btn--primary{border:0}
.bz-btn--secondary{border-color:var(--line)}
.bz-btn--on-dark.bz-btn--secondary{border-width:1.5px;border-color:rgba(255,255,255,.6)}
.bz-btn--on-dark.bz-btn--secondary:hover{background:rgba(255,255,255,.12);border-color:#fff;color:#fff}

/* Eyebrows are red, wide-tracked Oswald. */
.bz-eyebrow{font-family:var(--font-heading);font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.bz-section--bg-ink .bz-eyebrow{color:var(--accent)}

/* Nav is Oswald, uppercase, white on the grey header; red on hover. */
.bz-navitem>a,.bz-navlabel{font-family:var(--font-heading);font-weight:600;letter-spacing:.06em;text-transform:uppercase}

/* Sharp corners throughout — a deliberate brand choice, not an oversight. */
.bz-figure img,.bz-card,.bz-input{border-radius:0}

/* The type ramp the desktop sizes are drawn to does not fit a phone. */
@media (max-width:1100px){
  .bz-block h1{font-size:60px}
  .bz-block h2{font-size:34px}
}
@media (max-width:640px){
  .bz-block h1{font-size:44px}
  .bz-block h2{font-size:28px}
}

/* Skip link — off-screen until focused. */
.tc-skip{position:absolute;left:-999px;top:0;z-index:100;background:#fff;color:#14151A;padding:12px 16px;font:600 14px var(--font-body);text-decoration:none}
.tc-skip:focus{left:8px;top:8px}
/* ---------------- inner-page component system (handoff §"Inner-page") ----- */

/* Form card: 2-up fields, labels Inter 600 15px, square 48px inputs, red focus
   ring. The renderer puts the fields straight inside <form>, so the grid lives
   there and everything that is not a half-width field spans the row. */
.bz-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:20px;background:none;border:0;border-radius:0;padding:0;max-width:none}
.bz-form > *{grid-column:1/-1}
.bz-form > .bz-field--half{grid-column:auto}
.bz-form__t{font-family:var(--font-heading);font-weight:600;font-size:20px;letter-spacing:.04em;text-transform:uppercase;margin:0}
.bz-field{display:flex;flex-direction:column;gap:6px}
.bz-label{font-family:var(--font-body);font-weight:600;font-size:15px;color:#14151A}
.bz-req{color:#C41230}
.bz-input{font:400 16px var(--font-body);padding:12px 14px;min-height:48px;box-sizing:border-box;width:100%;border:1px solid #54565C;border-radius:0;background:#fff;color:#14151A}
.bz-input:focus-visible{outline:3px solid #C41230;outline-offset:1px}
textarea.bz-input{min-height:120px}
.bz-help{font-size:13px;color:#54565C;margin:0}
.bz-form__status{font-size:14px;font-weight:600;color:#A00F27;margin:0}
.bz-field--consent .bz-choice{display:grid;grid-template-columns:24px 1fr;gap:12px;align-items:start;font-size:15px;line-height:1.5;cursor:pointer}
.bz-field--consent input[type="checkbox"]{width:24px;height:24px;accent-color:#C41230;margin:0}
.bz-field--hp{position:absolute;left:-9999px}
.bz-form > button[type="submit"]{width:100%;min-height:56px;background:#C41230;color:#fff;border:0;border-radius:0;font-family:var(--font-heading);font-weight:600;font-size:16px;letter-spacing:.1em;text-transform:uppercase;padding:16px 24px}
.bz-form > button[type="submit"]:hover{background:#8f0d21;color:#fff}

/* FAQ: a divider per row, Oswald questions, and a red "+" that turns on open. */
.bz-faqs{border-top:1px solid #EDEBE3}
.bz-faq{border-bottom:1px solid #EDEBE3}
.bz-faq > summary{display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer;list-style:none;padding:20px 0;font-family:var(--font-heading);font-weight:600;font-size:18px;letter-spacing:.02em;color:#14151A}
.bz-faq > summary::-webkit-details-marker{display:none}
.bz-faq > summary::after{content:"+";color:#C41230;font:700 28px/1 var(--font-heading);transition:transform .2s ease}
.bz-faq[open] > summary::after{transform:rotate(45deg)}
.bz-faq__a{padding:0 0 20px;color:#54565C;font-size:16px;line-height:1.6;max-width:80ch}
@media (prefers-reduced-motion:reduce){.bz-faq > summary::after{transition:none}}

/* The "helpful to have on hand" list is a feature list at one column. */
.bz-block--list .bz-grid--1{grid-template-columns:1fr;gap:4px}
.bz-block--list .bz-grid--1 li{list-style:disc;margin-left:20px;color:#54565C}
.bz-block--list .bz-grid--1 li .bz-feat__l{font-weight:400;font-size:16px}

/* Site-map strip and footer row: inline link rows. */
[data-bz-node="sm-strip-links"] p{display:flex;flex-wrap:wrap;gap:20px;align-items:center;margin:0;font-size:14px;color:#fff}
[data-bz-node="sm-strip-links"] a{color:#fff;text-decoration:none}
[data-bz-node="sm-strip-links"] a:hover{color:#ff8da0}
[data-bz-node="sm-strip-links"] small{font-family:var(--font-heading);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#8F8F8F}
[data-bz-node="sm-foot-links"] p{display:flex;flex-wrap:wrap;gap:20px;align-items:center;margin:0;font-size:14px}
[data-bz-node="sm-foot-links"] small{font-family:var(--font-heading);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#54565C}
[data-bz-node="sm-title"] h1{font-family:var(--font-heading);font-weight:700;font-size:clamp(32px,5vw,56px);line-height:1;text-transform:none;margin:0}
[data-bz-node="sm-count"] p{font-size:14px;color:#54565C;margin:0;text-align:right}
@media (max-width:640px){[data-bz-node="sm-count"] p{text-align:left}}

/* The form card carries no title of its own in this design. */
.bz-form__t{display:none}

/* A feature list standing in for a plain bulleted list. */
.bz-block--list .bz-grid--1{grid-template-columns:1fr;gap:4px;list-style:disc;padding-left:20px}
.bz-block--list .bz-grid--1 .bz-feature__t{font:400 16px/1.6 var(--font-body);color:#54565C;text-transform:none;margin:0}
.bz-block--list .bz-grid--1 .bz-feature{display:list-item;color:#54565C}

/* FAQ rows sit on the page, not on a card. */
.bz-faqs{background:none}

/* The breadcrumb sits directly under the header, with no block padding. */
.bz-block--breadcrumb{padding-block:0}

/* ------------------------------------------------------- blog posts (/news) */
/* The platform composes a post as masthead + body; these are the handoff's
   measurements for that shape. */
article > .bz-block:first-child {
  background: #0E0F13; color: #fff; margin-top: 16px;
  border-bottom: 6px solid #C41230;
  padding-block: clamp(56px, 8vw, 100px);
}
article > .bz-block:first-child .bz-prose { max-width: none }
article > .bz-block:first-child .bz-eyebrow {
  font-family: var(--font-heading); font-weight: 600; font-size: 14px;
  letter-spacing: .12em; text-transform: uppercase; color: #fff;
  margin: 0 0 16px; border-left: 4px solid #C41230; padding-left: 12px;
}
article > .bz-block:first-child h1 {
  font-family: var(--font-heading); font-weight: 700;
  font-size: clamp(32px, 5vw, 64px); line-height: 1.05;
  text-transform: uppercase; margin: 0; max-width: 1000px; color: #fff;
}
article .bz-block--customHtml { padding-block: clamp(56px, 8vw, 100px) 0 }
article .bz-custom {
  max-width: 760px; margin: 0 auto; display: grid; gap: 22px;
  font-size: 18px; line-height: 1.65;
}
article .bz-custom > p { margin: 0 }
article .bz-custom figure { margin: 0; display: grid; gap: 10px }
article .bz-custom figure img { display: block; width: 100%; max-width: 640px; height: auto }
article .bz-custom figcaption { font-size: 14px; line-height: 1.5; color: #54565C }
article .bz-custom :is(h2, h3) { margin: 0; font-family: var(--font-heading); text-transform: uppercase }
article .bz-custom ul, article .bz-custom ol { margin: 0; padding-left: 22px; display: grid; gap: 10px }

/* Previous / next cards, which the post body carries. */
.tc-postnav {
  max-width: 760px; margin: clamp(48px, 7vw, 80px) auto 0;
  display: flex; flex-wrap: wrap; gap: 20px;
}
.tc-postnav__a {
  flex: 1 1 280px; background: #fff;
  border: 1px solid #EDEBE3; border-top: 4px solid #C41230;
  padding: 20px 24px; text-decoration: none; color: #14151A;
}
.tc-postnav__a:hover { box-shadow: 0 24px 48px -20px rgba(0, 0, 0, .18); color: #14151A }
.tc-postnav__k {
  display: block; font-family: var(--font-heading); font-weight: 600; font-size: 13px;
  letter-spacing: .1em; text-transform: uppercase; color: #C41230; margin-bottom: 6px;
}
.tc-postnav__t { display: block; font-weight: 600; line-height: 1.4 }

/* ------------------------------------------------------- news index (/news) */
.tc-news .bz-bare {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 20px; align-items: start;
}
.tc-news .bz-loc {
  background: #fff; border: 1px solid #EDEBE3; border-top: 4px solid #C41230;
  padding: 24px; display: grid; gap: 10px;
}
.tc-news .bz-loc:hover { box-shadow: 0 24px 48px -20px rgba(0, 0, 0, .18) }
.tc-news .bz-loc a { text-decoration: none }
.tc-news .bz-loc strong {
  font-family: var(--font-heading); font-weight: 600; font-size: 20px;
  line-height: 1.25; color: #14151A; display: block;
}
.tc-news .bz-loc a:hover strong { color: #C41230 }
.tc-news .bz-loc__s { font-size: 16px; line-height: 1.6; color: #54565C }
.tc-news .bz-loc[hidden] { display: none }
.tc-pager { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 40px; justify-content: center }
.tc-pager a {
  font-family: var(--font-heading); font-weight: 600; font-size: 14px; letter-spacing: .08em;
  min-width: 44px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center;
  padding: 0 14px; border: 1px solid #EDEBE3; background: #fff; color: #14151A; text-decoration: none;
}
.tc-pager a[aria-current="page"] { background: #C41230; border-color: #C41230; color: #fff }
.tc-pager a:hover:not([aria-current]) { border-color: #C41230; color: #C41230 }

/* ------------------------------------------------------------- site chrome */
/* Lives here rather than on the template because the generated blog index is
   rendered with no page CSS at all (scripts/build.mjs), so template CSS and
   node styles never reach it. One source, every surface. */
[data-bz-node="utility"]{padding-block:10px;font-size:12px;line-height:1.6}
[data-bz-node="utility-row"]{display:flex;justify-content:space-between;align-items:center;gap:16px}
[data-bz-node="utility"] p{margin:0}
[data-bz-node="utility"] p,[data-bz-node="utility"] a{font-size:12px;line-height:1.6;color:#fff}
[data-bz-node="utility"] .bz-navitem > a{font-family:var(--font-body);font-weight:400;font-size:12px;letter-spacing:.04em;text-transform:none;color:#fff;padding-block:0;line-height:1.6}
[data-bz-node="utility"] .bz-navitem > a:hover,[data-bz-node="utility"] a:hover{color:#ff8da0}
[data-bz-node="utility"] .bz-nav{gap:24px}
[data-bz-node="utility-states"] a{color:#fff;text-decoration:none;letter-spacing:.08em}

[data-bz-node="header"]{padding-block:14px;background:#A6A6A6;border-width:0;border-bottom:1px solid #8F8F8F;position:sticky;top:0;z-index:50}
[data-bz-node="header-row"]{display:flex;justify-content:space-between;align-items:center;gap:24px}
[data-bz-node="header-brand"],[data-bz-node="header-nav"]{flex-shrink:1}
[data-bz-node="header"] .bz-menu-wrap{flex:0 1 auto}
[data-bz-node="header"] .bz-navitem > a{font-family:var(--font-heading);font-weight:500;font-size:14px;line-height:normal;letter-spacing:.1em;text-transform:uppercase;color:#14151A;padding-block:0}
[data-bz-node="header"] .bz-navitem > a:hover{color:#C41230}
[data-bz-node="header"] .bz-nav{gap:32px}
[data-bz-node="header-logo"],[data-bz-node="header-logo"] .bz-brand{display:flex;line-height:0}
[data-bz-node="header-logo"] img{object-fit:contain;width:220px;max-width:60vw;height:auto;display:block}
[data-bz-node="header-button"]{display:flex;justify-content:flex-end}
[data-bz-node="header-button"] .bz-btn{padding:14px 24px;letter-spacing:.1em}
[data-bz-node="header-account"]{display:none}
[data-bz-node="utility"] .bz-block,[data-bz-node="header"] .bz-block{padding-block:0}
[data-bz-node="header"] .bz-btns{margin-block:0}
[data-bz-node="header"] .bz-menu-toggle{width:44px;height:44px;background:#14151A;color:#fff;border:0;border-radius:0;justify-content:center}
[data-bz-node="header"] .bz-menu-toggle span{width:18px;background:#fff}
@media (max-width:1100px){
  [data-bz-node="header-cta"]{display:none}
  [data-bz-node="header-logo"] img{height:36px;width:auto}
  [data-bz-node="header"] .bz-menu-wrap[data-open] > .bz-menu{background:#14151A;border-bottom:0;padding:8px 32px 24px}
  [data-bz-node="header"] .bz-menu-wrap[data-open] .bz-nav{gap:0}
  [data-bz-node="header"] .bz-menu-wrap[data-open] .bz-navitem{width:100%;border-bottom:1px solid #45474E}
  [data-bz-node="header"] .bz-menu-wrap[data-open] .bz-navitem > a{display:block;color:#fff;font-size:16px;padding:14px 0}
  [data-bz-node="header"] .bz-menu-wrap[data-open] .bz-navitem > a:hover{color:#fff}
}

[data-bz-node="footer"]{background:#0E0F13;padding-top:64px;padding-bottom:40px}
[data-bz-node="footer-row"]{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:40px;padding-bottom:40px}
[data-bz-node="footer-row"] > .bz-col{grid-column:auto}
[data-bz-node="footer-bottom"]{border-width:0;border-top:1px solid #2a2c33;padding-top:24px}
[data-bz-node="footer-logo"]{margin-bottom:20px}
[data-bz-node="footer-logo"] img{width:260px;max-width:100%;height:auto}
[data-bz-node="footer-blurb"] p{font-size:14px;line-height:1.7;color:#D6D6D8;margin:0;max-width:280px}
[data-bz-node="footer-links"] .bz-navitem > a{font-family:var(--font-body);font-weight:400;font-size:14px;letter-spacing:0;text-transform:none;color:#D6D6D8}
[data-bz-node="footer-links"] .bz-navitem > a:hover{color:#fff}
[data-bz-node="footer-links"] .bz-nav{gap:12px}
[data-bz-node="footer-links-head"] h2{font-family:var(--font-heading);font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#fff;margin:0 0 18px}
[data-bz-node="footer-copy"] p,[data-bz-node="footer-credit"] p{font-size:12px;color:#D6D6D8;margin:0}
[data-bz-node="footer-copy"] a{color:#D6D6D8}
[data-bz-node="footer-copy"] a:hover{color:#fff}
[data-bz-node="footer-credit"]{display:flex;align-items:center;justify-content:flex-end;gap:8px}
[data-bz-node="footer-credit-text"] p{white-space:nowrap}
[data-bz-node="footer-credit-logo"] img{width:auto;height:26px}
@media (max-width:1100px){[data-bz-node="footer-row"]{grid-template-columns:1fr 1fr;gap:32px}}
@media (max-width:640px){[data-bz-node="footer-row"]{grid-template-columns:1fr}[data-bz-node="footer-credit"]{justify-content:flex-start}}

/* ----------------------------------------------------- split band (both) */
/* Shared by split-band and split-band-reverse, which differ only in column
   order and so carry the same node ids. */
[data-bz-node="sb-copy"] .bz-eyebrow{color:#C41230;font-family:var(--font-heading);font-weight:600;font-size:13px;letter-spacing:.14em;text-transform:uppercase;margin:0 0 12px}
[data-bz-node="sb-copy"] h2{font-family:var(--font-heading);font-weight:700;font-size:clamp(28px,4vw,42px);line-height:1.1;text-transform:uppercase;letter-spacing:0;margin:0 0 24px}
[data-bz-node="sb-cta"] .bz-btn--primary{background:#C41230;color:#fff;border:0;padding:16px 32px;font-family:var(--font-heading);font-weight:600;font-size:15px;letter-spacing:.1em;text-transform:uppercase;border-radius:0}
[data-bz-node="sb-cta"] .bz-btn--primary:hover{background:#8f0d21;color:#fff}
[data-bz-node="sb-body"] p{color:#54565C;font-size:16px;line-height:1.6;margin:0 0 16px}
[data-bz-node="sb-body"] p:last-child{margin-bottom:0}
[data-bz-node="sb-photo"] img{width:100%;height:auto;display:block;border-radius:0}
[data-bz-node="sb-media"] .bz-block,[data-bz-node="sb-media"] .bz-container{padding:0}
[data-bz-node="sb-cta"]{margin-top:24px}

